            template_version: number;
            /** @description Optional exact decoded QR text. New printed QR is B1:{template_id}:{revision}:{page_number}; legacy B1:{template_id}:{page_number} denotes revision 16. The browser validates recognized QR values against this upload; unknown values may remain opaque. */
            qr_raw?: string;
